async function executeSearchNotes(app, args) {
  const { query, searchIn = "both", maxResults = 10, folder } = args;
  const allFiles = app.vault.getMarkdownFiles();
  let filteredFiles = allFiles;
  if (folder) {
    filteredFiles = allFiles.filter((f) => f.path.startsWith(folder));
  }
  const results = [];
  for (const file of filteredFiles) {
    if (results.length >= maxResults)
      break;
    if (searchIn === "filename" || searchIn === "both") {
      if (file.basename.toLowerCase().includes(query.toLowerCase()) || file.name.toLowerCase().includes(query.toLowerCase())) {
        results.push({
          path: file.path,
          matchType: "\u6587\u4EF6\u540D",
          preview: file.path
        });
        continue;
      }
    }
    if (searchIn === "content" || searchIn === "both") {
      const content = await app.vault.read(file);
      const lowerContent = content.toLowerCase();
      const lowerQuery = query.toLowerCase();
      const index = lowerContent.indexOf(lowerQuery);
      if (index !== -1) {
        const start = Math.max(0, index - 40);
        const end = Math.min(content.length, index + query.length + 40);
        let preview = content.substring(start, end);
        if (start > 0)
          preview = "..." + preview;
        if (end < content.length)
          preview = preview + "...";
        results.push({
          path: file.path,
          matchType: "\u5185\u5BB9",
          preview
        });
      }
    }
  }
  if (results.length === 0) {
    return `\u672A\u627E\u5230\u4E0E "${query}" \u76F8\u5173\u7684\u7B14\u8BB0\u3002`;
  }
  const resultsText = results.map(
    (r, i) => `${i + 1}. **${r.path}**\uFF08${r.matchType}\u5339\u914D\uFF09
   \`${r.preview}\``
  ).join("\n\n");
  let summary = `\u{1F50D} \u641C\u7D22 "${query}" \u627E\u5230 ${results.length} \u6761\u7ED3\u679C`;
  if (allFiles.length > filteredFiles.length) {
    summary += `\uFF08\u5728 ${folder} \u4E2D\u641C\u7D22\uFF09`;
  }
  return summary + ":\n\n" + resultsText;
}
