function collectItems(folder, recursive, maxResults, prefix = "") {
  const items = [];
  const children = folder.children;
  for (const child of children) {
    if (items.length >= maxResults)
      break;
    if (child instanceof import_obsidian5.TFolder) {
      items.push(`\u{1F4C1} ${prefix}${child.name}/`);
      if (recursive) {
        items.push(
          ...collectItems(child, recursive, maxResults - items.length, prefix + "  ")
        );
      }
    } else {
      const ext = child.extension;
      const icon = ext === "md" ? "\u{1F4DD}" : ext === "canvas" ? "\u{1F3A8}" : "\u{1F4CE}";
      items.push(`${icon} ${prefix}${child.name}`);
    }
  }
  return items;
}
async function executeListFiles(app, args) {
  const { folder: folderPath, recursive = false, maxResults = 50 } = args;
  let targetFolder;
  if (folderPath) {
    const item = app.vault.getAbstractFileByPath(folderPath);
    if (!item || !(item instanceof import_obsidian5.TFolder)) {
      return `\u9519\u8BEF\uFF1A\u627E\u4E0D\u5230\u6587\u4EF6\u5939 "${folderPath}"\u3002`;
    }
    targetFolder = item;
  } else {
    targetFolder = app.vault.getRoot();
  }
  const items = collectItems(targetFolder, recursive, maxResults);
  if (items.length === 0) {
    return `\u{1F4C2} "${folderPath || "/"}" \u76EE\u5F55\u4E3A\u7A7A\u3002`;
  }
  const header = `\u{1F4C2} **${folderPath || "/"}**\uFF08\u5171 ${items.length} \u9879\uFF09\uFF1A

`;
  return header + items.join("\n");
}
