        statusReady: "\u6E96\u5099\u5B8C\u4E86",
        statusThinking: "\u8003\u3048\u4E2D...",
        displayName: "Sedimind",
        ribbonTooltip: "Sedimind",
        welcomeHeader: "Sedimind",
        welcomeBody: `<p>\u3053\u3093\u306B\u3061\u306F\uFF01Obsidian\u30CE\u30FC\u30C8\u30A2\u30B7\u30B9\u30BF\u30F3\u30C8\u3067\u3059\u3002\u4EE5\u4E0B\u306E\u3053\u3068\u304C\u3067\u304D\u307E\u3059\uFF1A</p>
<ul>
  <li>\u30CE\u30FC\u30C8\u4F5C\u6210 \u2014 \u65B0\u3057\u3044\u30CE\u30FC\u30C8\u3092\u4F5C\u6210</li>
  <li>\u30CE\u30FC\u30C8\u7DE8\u96C6 \u2014 \u65E2\u5B58\u306E\u30CE\u30FC\u30C8\u3092\u7DE8\u96C6</li>
  <li>\u30CE\u30FC\u30C8\u691C\u7D22 \u2014 Vault\u5185\u3092\u691C\u7D22</li>
  <li>\u30CE\u30FC\u30C8\u95B2\u89A7 \u2014 \u30CE\u30FC\u30C8\u306E\u5185\u5BB9\u3092\u8868\u793A</li>
  <li>\u30D5\u30A1\u30A4\u30EB\u4E00\u89A7 \u2014 \u30C7\u30A3\u30EC\u30AF\u30C8\u30EA\u69CB\u9020\u3092\u8868\u793A</li>
  <li>\u30CE\u30FC\u30C8\u524A\u9664 \u2014 \u4E0D\u8981\u306A\u30D5\u30A1\u30A4\u30EB\u3092\u524A\u9664</li>
  <li>\u30E1\u30BF\u30C7\u30FC\u30BF\u8868\u793A \u2014 \u30CE\u30FC\u30C8\u306E\u30D7\u30ED\u30D1\u30C6\u30A3\u3092\u53D6\u5F97</li>
  <li>\u30B7\u30B9\u30C6\u30E0\u6642\u523B\u78BA\u8A8D \u2014 \u73FE\u5728\u306E\u65E5\u6642\u3092\u53D6\u5F97</li>
</ul>
<p>\u4F55\u3092\u3057\u305F\u3044\u304B\u6559\u3048\u3066\u304F\u3060\u3055\u3044\uFF01</p>`,
