      const feedbackTypeSelect = feedbackForm.querySelector("select");
      const feedbackContentTextarea = feedbackForm.querySelector("textarea");
      const feedbackType = (feedbackTypeSelect == null ? void 0 : feedbackTypeSelect.value) || "bug";
      const feedbackContent = (feedbackContentTextarea == null ? void 0 : feedbackContentTextarea.value) || "";
      const typeLabels = {
        bug: this.str("feedbackTypeBug"),
        feature: this.str("feedbackTypeFeature"),
        other: this.str("feedbackTypeOther")
      };
      const title = `[${typeLabels[feedbackType]}] Feedback`;
      const body = encodeURIComponent(feedbackContent);
