      window.open(newIssueUrl, "_blank");
      submitBtn.setText(this.str("feedbackSuccess"));
      submitBtn.disabled = true;
      setTimeout(() => {
        submitBtn.setText(this.str("feedbackSubmit"));
        submitBtn.disabled = false;
      }, 3e3);
