    new import_obsidian14.Setting(container).setName("\u81EA\u5B9A\u4E49\u5212\u8BCD\u5DE5\u5177\u680F").setDesc("\u4E3B\u680F\u6309\u94AE\u53EF\u52FE\u9009\u663E\u793A\u5E76\u62D6\u62FD\u6392\u5E8F\uFF1B\u6587\u672C\u5DE5\u5177\u5B50\u83DC\u5355\u53EF\u52FE\u9009\u6DFB\u52A0\u683C\u5F0F\u9879\u5E76\u6392\u5E8F\u3002\u4FEE\u6539\u5373\u65F6\u4FDD\u5B58\u3002");
