      { id: "new-chat", key: "cmdNewChat", desc: "\u5728\u5BF9\u8BDD\u9762\u677F\u4E2D\u65B0\u5EFA\u4E00\u4E2A\u7A7A\u767D\u6807\u7B7E\u9875" },
      { id: "edit-selection", key: "cmdEditSelection", desc: "\u5F15\u7528\u7F16\u8F91\u5668\u4E2D\u9009\u4E2D\u7684\u6587\u5B57\uFF0C\u81EA\u52A8\u586B\u5165\u4FEE\u6539\u6307\u4EE4" },
      { id: "ai-summarize-active-note", key: "cmdSummarize", desc: "\u81EA\u52A8\u6458\u8981\u5F53\u524D\u6D3B\u52A8\u7B14\u8BB0\u5185\u5BB9" }
