// src/utils.ts
function isMobile() {
  if (typeof navigator === "undefined")
    return false;
  const userAgent = navigator.userAgent.toLowerCase();
  return /android|iphone|ipad|ipod/.test(userAgent);
}
function isDesktop() {
  return !isMobile();
}
function getPlatform() {
  return isMobile() ? "mobile" : "desktop";
}

