// src/mcp/McpManager.ts
var import_obsidian19 = require("obsidian");
var McpManager6 = class {
  constructor(app) {
    this.clients = /* @__PURE__ */ new Map();
    this.app = app;
  }
  /** 获取所有连接信息（用于 UI 展示） */
  getConnectionInfos() {
    return Array.from(this.clients.values()).map((client) => ({
      config: client.getConfig(),
      state: client.getState(),
      tools: client.getTools()
    }));
  }
  /** 连接单个服务器 */
  async connectServer(config) {
    if (isMobile()) {
      new import_obsidian19.Notice("MCP \u529F\u80FD\u5728\u79FB\u52A8\u8BBE\u5907\u4E0A\u4E0D\u53EF\u7528");
      throw new Error("MCP \u529F\u80FD\u5728\u79FB\u52A8\u8BBE\u5907\u4E0A\u4E0D\u53EF\u7528");
    }
    if (this.clients.has(config.id)) {
      await this.disconnectServer(config.id);
    }
    const client = new McpClient(config);
    this.clients.set(config.id, client);
    try {
      return await client.connect();
    } catch (error) {
      console.error(`[McpManager] Failed to connect to "${config.name}":`, error);
      throw error;
    }
  }
  /** 断开指定服务器 */
  async disconnectServer(id) {
    const client = this.clients.get(id);
    if (client) {
      client.disconnect();
      this.clients.delete(id);
    }
  }
  /** 断开所有服务器 */
  disconnectAll() {
    for (const [id] of this.clients) {
      this.disconnectServer(id);
    }
  }
  /** 获取所有已连接服务器的工具定义（供 LLM Function Calling 使用） */
  getAllMcpToolDefinitions() {
    const definitions = [];
    for (const client of this.clients.values()) {
      if (client.getState() !== "connected")
        continue;
      const config = client.getConfig();
      for (const tool of client.getTools()) {
        definitions.push(this.mcpToolToDefinition(tool, config.name));
      }
    }
    return definitions;
  }
  /** 执行 MCP 工具调用 */
  async callMcpTool(name, args) {
    for (const client of this.clients.values()) {
      if (client.getState() !== "connected")
        continue;
      const config = client.getConfig();
      const prefixedName = `mcp__${config.id}__`;
      if (name.startsWith(prefixedName)) {
        const toolName = name.slice(prefixedName.length);
        return await client.callTool(toolName, args);
      }
      const found = client.getTools().find((t2) => t2.name === name);
      if (found) {
        return await client.callTool(name, args);
      }
    }
    return `\u9519\u8BEF\uFF1A\u672A\u627E\u5230\u5DF2\u8FDE\u63A5\u7684 MCP \u5DE5\u5177 "${name}"\u3002`;
  }
  /** 将 MCP Tool 转换为 LLM ToolDefinition */
  mcpToolToDefinition(tool, serverName) {
    const toolName = `mcp__${serverName.replace(/[^a-zA-Z0-9_-]/g, "_")}__${tool.name}`;
    const description = tool.description ? `[MCP:${serverName}] ${tool.description}` : `[MCP:${serverName}] ${tool.name}`;
    return {
      type: "function",
      function: {
        name: toolName,
        description,
        parameters: {
          type: "object",
          properties: tool.inputSchema.properties || {},
          required: tool.inputSchema.required || []
        }
      }
    };
  }
};

